import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportGeneratorServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final Set<String> ALLOWED_REPORTS = Set.of("sales", "inventory", "audit");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String format = req.getParameter("format");
        String locale = req.getParameter("locale");

        // Validate report type against whitelist
        if (reportType == null || !ALLOWED_REPORTS.contains(reportType)) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid report type");
            return;
        }

        // Validate format
        if (format == null || !format.matches("^(pdf|csv|html)$")) {
            format = "pdf";
        }

        // Build template path - locale is user-controlled
        String templatePath = TEMPLATE_DIR + reportType + "/" + locale + "/template.xml";

        // Read template file
        File templateFile = new File(templatePath);
        if (!templateFile.exists()) {
            // Fallback to default locale
            templatePath = TEMPLATE_DIR + reportType + "/en_US/template.xml";
            templateFile = new File(templatePath);
        }

        String templateContent;
        try (BufferedReader reader = new BufferedReader(new FileReader(templateFile))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
            templateContent = sb.toString();
        }

        // Fetch report data from database
        Map<String, String> reportData = fetchReportData(reportType, req.getParameter("quarter"));

        // Substitute placeholders in template
        StringSubstitutor sub = new StringSubstitutor(reportData);
        String rendered = sub.replace(templateContent);

        // Set response headers
        resp.setContentType(getContentType(format));
        resp.setHeader("Content-Disposition", "attachment; filename=report." + format);
        resp.setHeader("X-Report-Locale", locale != null ? locale : "en_US");
        resp.getWriter().write(rendered);
    }

    private Map<String, String> fetchReportData(String reportType, String quarter) {
        Map<String, String> data = new HashMap<>();
        String q = (quarter != null && quarter.matches("^Q[1-4]_\\d{4}$")) ? quarter : "Q1_2024";

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT metric_name, metric_value FROM report_metrics WHERE report_type = ? AND quarter = ?")) {
            ps.setString(1, reportType);
            ps.setString(2, q);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    data.put(rs.getString("metric_name"), rs.getString("metric_value"));
                }
            }
        } catch (SQLException e) {
            data.put("error", "Data unavailable");
        }
        return data;
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS"));
    }

    private String getContentType(String format) {
        return switch (format) {
            case "csv" -> "text/csv";
            case "html" -> "text/html";
            default -> "application/pdf";
        };
    }
}
